const re = /<script(?![^>]*\bsrc\s*=)[^>]*>([\s\S]*?)<\/script>/gi;
let m, i = 0, scripts = [];
while ((m = re.exec(html)) !== null) {
  scripts.push(m[1]);
  try {
    new Function(m[1]);
    console.log(`[OK]   inline-скрипт #${i}: синтаксис корректен (${m[1].length} симв.)`);
  } catch (e) {
    console.log(`[FAIL] inline-скрипт #${i}: ${e.message}`);
    fail.push("синтаксис #" + i);
  }
  i++;
}
ok(scripts.length >= 1, `найдено inline-скриптов: ${scripts.length}`);

// ---------- 2. внешние загрузки ----------
const ext = [];
for (const r of [/\bsrc\s*=\s*["']([^"']+)["']/gi, /\bhref\s*=\s*["']([^"']+)["']/gi, /@import[^;]+;/gi]) {
  for (const mm of html.matchAll(r)) {
    const v = (mm[1] || mm[0]).trim();
    if (/^(https?:)?\/\//i.test(v)) ext.push(v);
  }
